    const AnimalDefinition *FindAnimal(std::string_view nameOrGuid) {
        for (const auto &animal : g_Animals) {
            if (animal.name == nameOrGuid || animal.soulGuid == nameOrGuid) {
                return &animal;
            }
        }
        return nullptr;
    }
